      loadData = function()
        if not fileSystemAvailable then
          return
        end
        local function getValue(data, frame, data2)
          if not data then
            return data2
          end
          local viewportSize = WorkspaceRoot.CurrentCamera.ViewportSize
          local udim2 = UDim2.new(data[1], data[2], data[3], data[4])
          local calculatedValue = udim2.X.Scale * viewportSize.X + udim2.X.Offset
          local calculatedValue2 = udim2.Y.Scale * viewportSize.Y + udim2.Y.Offset
          local x = frame and frame.AbsoluteSize.X or 100
          return calculatedValue > -x + 50
              and calculatedValue < viewportSize.X - 50
              and calculatedValue2 > 0
              and calculatedValue2 < viewportSize.Y - 50
              and udim2
            or data2
        end
        ScrollingFrame.Position = UDim2.new(0, _G.isMobile and 5 or 17, 1, _G.isMobile and -140 or -419)
        bottomRightButtonsFrame.Position = UDim2.new(1, _G.isMobile and -10 or -20, 1, _G.isMobile and -15 or -25)
        parent2.Position = UDim2.new(1, _G.isMobile and -115 or -430, 1, _G.isMobile and -250 or -302)
        proximityFrame.Position = UDim2.new(1, _G.isMobile and -200 or -420, 1, _G.isMobile and -425 or -510)
        if isfile("UIPositions.json") then
          local success, callResult = pcall(function()
            return readfile("UIPositions.json")
          end)
          if success then
            local success, callResult = pcall(function()
              return HttpService:JSONDecode(callResult)
            end)
            if success and callResult then
              if callResult.playerListPos then
                ScrollingFrame.Position = getValue(callResult.playerListPos, ScrollingFrame, ScrollingFrame.Position)
              end
              if callResult.commandFramePos then
                parent2.Position = getValue(callResult.commandFramePos, parent2, parent2.Position)
              end
              if callResult.proximityFramePos then
                proximityFrame.Position =
                  getValue(callResult.proximityFramePos, proximityFrame, proximityFrame.Position)
              end
              if callResult.bottomRightPos then
                bottomRightButtonsFrame.Position =
                  getValue(callResult.bottomRightPos, bottomRightButtonsFrame, bottomRightButtonsFrame.Position)
              end
              if callResult.statsFramePos then
                rootPart.Position = getValue(callResult.statsFramePos, rootPart, rootPart.Position)
              end
              if callResult.unlockContainerPos and _G.unlockContainer then
                _G.unlockContainer.Position =
                  getValue(callResult.unlockContainerPos, _G.unlockContainer, _G.unlockContainer.Position)
              end
              if callResult.stealProgressPos then
                _G._savedStealProgressPos = callResult.stealProgressPos
              end
              if callResult.uiLocked ~= nil then
                uiLocked_ = callResult.uiLocked
                isEnabled5 = uiLocked_
                if not isEnabled5 then
                  local frame = rootPart
                  local backgroundColor3 = buttonGlowColorLocal502
                  rootPart.BackgroundTransparency = 0.95
                  frame.BackgroundColor3 = backgroundColor3
                else
                  rootPart.BackgroundTransparency = 1
                end
              end
              if callResult.walkspeedFramePos then
                _G.savedWalkspeedFramePos = callResult.walkspeedFramePos
              end
              if callResult.selectTargetFramePos then
                _G.savedSelectTargetFramePos = callResult.selectTargetFramePos
              end
              if callResult.remoteSellPos then
                _G.savedRemoteSellPos = callResult.remoteSellPos
              end
              if keybinds and callResult.colorTheme and not keybinds.ColorTheme then
                keybinds.ColorTheme = callResult.colorTheme
              end
              if callResult.backgroundColor and callResult.buttonGlowColor then
                local color2 = Color3.new(
                  callResult.backgroundColor[1],
                  callResult.backgroundColor[2],
                  callResult.backgroundColor[3]
                )
                local color3 = Color3.new(
                  callResult.buttonGlowColor[1],
                  callResult.buttonGlowColor[2],
                  callResult.buttonGlowColor[3]
                )
                if not keybinds or not keybinds.ColorTheme then
                  updateLabel(color2, color3)
                end
              end
            end
          end
        end
