    local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
    if not humanoidRootPart then
      return
    end
    local position = humanoidRootPart.Position
    local amount = 15
    local state = nil
    local state2 = nil
    local plots = WorkspaceRoot:FindFirstChild("Plots")
    if not plots then
      return
    end
    for _, child in pairs(plots:GetChildren()) do
      if child.Name ~= localPlayer.Name then
        local animalPodiums = child:FindFirstChild("AnimalPodiums")
        if animalPodiums then
          for _, child2 in pairs(animalPodiums:GetChildren()) do
            pcall(function()
              local position2 = child2:GetPivot().Position
              local magnitude = (position2 - position).Magnitude
              if magnitude < amount then
                amount = magnitude
                state = position2
                state2 = child
              end
            end)
          end
        end
      end
    end
    if state and state2 then
      local state = getValue(position.Y)
      if state == 3 then
        state = 2
      end
      if state >= 1 and state <= 3 then
        findTarget(state2, state)
      end
    end
  end
  local isEnabled = false
  localPlayer:GetAttributeChangedSignal("Stealing"):Connect(function()
    local attribute = localPlayer:GetAttribute("Stealing")
    if _G.AutoUnlockDuringSteal and attribute and not isEnabled then
      findTarget2()
    end
    isEnabled = attribute
  end)
end)
