            if localPlayer:GetAttribute("Stealing") and not _G.walkspeedEnabled and _G.toggleWalkspeed then
              pcall(_G.toggleWalkspeed)
            end
          end)
        end
        if not attribute and isEnabled then
          if not walkspeedEnabled and _G.walkspeedEnabled and _G.toggleWalkspeed then
            pcall(_G.toggleWalkspeed)
          end
        end
        isEnabled = attribute
      end
    end
  end)
end)
